KG42.register("rules-f1cc675fc98ab4d8e2024da6",{"id":"11-p2p_mechanisms_evaluation::v141-c-R008","paper":"11-p2p_mechanisms_evaluation","record":{"rule_id":"v141-c-R008","mechanism_id":"v141-a-M01","name":"Local clearing price","process_stage":"pricing","market_meaning":"Submitted supply quantities, represented by negative net-energy bids, feed the regional supply-and-demand ratio used to calculate internal prices. Scope: SDR internal pricing within one energy sharing region. Submitted demand quantities, represented by nonnegative net-energy bids, feed the regional supply-and-demand ratio used to calculate internal prices. Scope: SDR internal pricing within one energy sharing region. The coordinator runs the pricing model to generate internal trading prices for issue to participants. Scope: Coordinator pricing in the P2P simulation framework and its SDR realization. Internal prices must be bounded between the retailer's export and retail prices. Scope: P2P framework under the stated passive-retailer assumptions. Condition: The retailer offers or purchases unlimited power at pre-announced retail and export prices, with the export price lower than the retail price. Both the internal selling price and the internal buying price equal the retailer's export price. Scope: SDR internal buying and selling prices at a given time step. Condition: The regional supply and demand ratio exceeds one.","independence_rationale":"Relations governed by the approved function pricing.local under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["bidding.demand","bidding.supply","coordination.local_operator","pricing.local"],"E":[{"edge_id":"v141-c-R008-E001","source":"bidding.demand","target":"pricing.local","type":"links","constraint_ids":["v141-c-R008-C002"],"evidence_ids":["v141-b-g07-ev-05"]},{"edge_id":"v141-c-R008-E002","source":"bidding.supply","target":"pricing.local","type":"links","constraint_ids":["v141-c-R008-C001"],"evidence_ids":["v141-b-g07-ev-05"]},{"edge_id":"v141-c-R008-E003","source":"coordination.local_operator","target":"pricing.local","type":"links","constraint_ids":["v141-c-R008-C003"],"evidence_ids":["v141-b-g02-e11","v141-b-g07-ev-05"]}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"pricing","context_text":"Coordinator pricing in the P2P simulation framework and its SDR realization. | P2P framework under the stated passive-retailer assumptions. | SDR internal buying and selling prices at a given time step. | SDR internal pricing within one energy sharing region.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g02-e11","v141-b-g02-e16","v141-b-g07-ev-05"]},"x":[],"theta":[{"parameter_id":"theta-r-export","symbol":"r_t^{\\mathrm{export}}","meaning":"Export price between the coordinator and the retailer (as illustrated in Fig. 2 of the source): the price at which the energy sharing region's surplus electricity is sold to the retailer. Within this pricing rule it is an exogenous, pre-announced price; the source assumes retail and export prices are non-dynamic (known exactly by the coordinator beforehand, not changing with exchanged power/energy) and that the export price is lower than the retail price.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["t"],"evidence_ids":["v141-b-g07-ev-05","v141-b-g02-e16"]},{"parameter_id":"theta-r-retail","symbol":"r_t^{\\mathrm{retail}}","meaning":"Retail price between the coordinator and the retailer (as illustrated in Fig. 2 of the source): the price at which the energy sharing region imports electricity from the retailer. Like the export price it is exogenous and pre-announced (non-dynamic in this paper), and it is stated to be higher than the export price.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["t"],"evidence_ids":["v141-b-g07-ev-05","v141-b-g02-e16"]},{"parameter_id":"theta-e-bid-SDR","symbol":"e_{n,t}^{\\mathrm{bid}}","meaning":"Energy bid of prosumer agent n at time step t as received by the coordinator: a signed net-energy quantity, where negative values are supply bids (the set PA^-) and nonnegative values are demand bids (the set PA^+). Scope note: within this pricing rule the submitted bid is an exogenous input to the coordinator's price computation (it enters SDR_t per Formula (A21)); how the bid is produced from the prosumer decision-making model (source Formula (A18)) is governed by the bidding rules, not by this rule.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["n","t"],"evidence_ids":["v141-b-g07-ev-05","v141-b-g07-ev-04"]},{"parameter_id":"theta-p-external","symbol":"p^{\\mathrm{external}}","meaning":"The electricity price at which the coordinator agent trades with the retailer, comprising the prices at which the coordinator buys from and sells to the retailer (termed retail price and export price respectively in the paper). Assumed non-dynamic: known exactly by the coordinator beforehand and not changing with the amount of power and energy exchanged in real time. It is an argument of the coordinator's pricing model (Formula (6)).","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":[],"evidence_ids":["v141-b-g02-e10"]},{"parameter_id":"theta-e-bid","symbol":"e^{\\mathrm{bid}}","meaning":"Framework-level notation for the energy bid(s) received from the prosumer agents (the resulting load profile over the scheduling horizon) that, together with the external prices and the optional price bid, form the input of the coordinator's abstract pricing model (Formula (6)). Scope note: shared framework notation, declared here only as an argument of this rule's pricing model; in this rule's SDR realization the bids are the net-energy quantities e_{n,t}^{bid} of Formula (A18).","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":[],"evidence_ids":["v141-b-g02-e09","v141-b-g02-e10","v141-b-g02-e11"]},{"parameter_id":"theta-p-bid","symbol":"p^{\\mathrm{bid}}","meaning":"The price bid of a prosumer agent (e.g. the ascending cost plot of the generation units for economic dispatch as described in the source's Ref. [15]); it is optional, since in some mechanisms only the energy bid is needed (shown in brackets in the prosumer action set). It is an argument of the coordinator's abstract pricing function.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":[],"evidence_ids":["v141-b-g02-e09","v141-b-g02-e10"]}],"phi":[{"constraint_id":"v141-c-R008-C001","kind":"mathematical","role":"core","statement":"Submitted supply quantities, represented by negative net-energy bids, feed the regional supply-and-demand ratio used to calculate internal prices. Scope: SDR internal pricing within one energy sharing region.","expression":"\\sum_{n \\in \\mathcal{PA}^-} \\left| e_{n,t}^{\\mathrm{bid}} \\right| \\quad \\text{with} \\quad \\mathcal{PA}^- = \\{\\, n \\mid e_{n,t}^{\\mathrm{bid}} \u003c 0,\\ n \\in \\mathcal{PA} \\,\\}","formalization_origin":"source","template_id":null,"members":["bidding.supply","pricing.local"],"variable_refs":[],"parameter_refs":["theta-e-bid-SDR"],"evidence_ids":["v141-b-g07-ev-05"]},{"constraint_id":"v141-c-R008-C002","kind":"mathematical","role":"core","statement":"Submitted demand quantities, represented by nonnegative net-energy bids, feed the regional supply-and-demand ratio used to calculate internal prices. Scope: SDR internal pricing within one energy sharing region.","expression":"\\sum_{n \\in \\mathcal{PA}^+} e_{n,t}^{\\mathrm{bid}} \\quad \\text{with} \\quad \\mathcal{PA}^+ = \\{\\, n \\mid e_{n,t}^{\\mathrm{bid}} \\ge 0,\\ n \\in \\mathcal{PA} \\,\\}","formalization_origin":"source","template_id":null,"members":["bidding.demand","pricing.local"],"variable_refs":[],"parameter_refs":["theta-e-bid-SDR"],"evidence_ids":["v141-b-g07-ev-05"]},{"constraint_id":"v141-c-R008-C003","kind":"mathematical","role":"core","statement":"The coordinator runs the pricing model to generate internal trading prices for issue to participants. Scope: Coordinator pricing in the P2P simulation framework and its SDR realization.","expression":"p^{\\mathrm{internal}} = Pricing_{T}\\!\\left( p^{\\mathrm{external}}, e^{\\mathrm{bid}}, p^{\\mathrm{bid}} \\right)","formalization_origin":"source","template_id":null,"members":["coordination.local_operator","pricing.local"],"variable_refs":[],"parameter_refs":["theta-p-external","theta-e-bid","theta-p-bid"],"evidence_ids":["v141-b-g02-e11","v141-b-g07-ev-05"]},{"constraint_id":"v141-c-R008-C004","kind":"mathematical","role":"core","statement":"Internal prices must be bounded between the retailer's export and retail prices. Scope: P2P framework under the stated passive-retailer assumptions. Condition: The retailer offers or purchases unlimited power at pre-announced retail and export prices, with the export price lower than the retail price.","expression":"r_t^{\\mathrm{export}} \\le p_t^{\\mathrm{sell}} \\le r_t^{\\mathrm{retail}}, \\quad r_t^{\\mathrm{export}} \\le p_t^{\\mathrm{buy}} \\le r_t^{\\mathrm{retail}}, \\quad r_t^{\\mathrm{export}} \u003c r_t^{\\mathrm{retail}}","formalization_origin":"source","template_id":null,"members":["pricing.local"],"variable_refs":[],"parameter_refs":["theta-r-export","theta-r-retail"],"evidence_ids":["v141-b-g02-e16","v141-b-g07-ev-05"]},{"constraint_id":"v141-c-R008-C005","kind":"mathematical","role":"core","statement":"Both the internal selling price and the internal buying price equal the retailer's export price. Scope: SDR internal buying and selling prices at a given time step. Condition: The regional supply and demand ratio exceeds one.","expression":"p_t^{\\mathrm{sell}} = r_t^{\\mathrm{export}}, \\quad p_t^{\\mathrm{buy}} = r_t^{\\mathrm{export}}, \\quad \\text{for } SDR_t > 1","formalization_origin":"source","template_id":null,"members":["pricing.local"],"variable_refs":[],"parameter_refs":["theta-r-export"],"evidence_ids":["v141-b-g07-ev-05"]},{"constraint_id":"v141-c-R008-C006","kind":"mathematical","role":"core","statement":"The regional supply-and-demand ratio at a time step equals the total absolute negative (supply) net-energy bid over the participating prosumer agents divided by the total nonnegative (demand) net-energy bid over the participating prosumer agents; supply bidders are the agents with negative net-energy bids and demand bidders are the agents with nonnegative net-energy bids. Scope: SDR internal pricing within one energy sharing region at a given time step.","expression":"SDR_t = \\frac{\\sum_{n \\in \\mathcal{PA}^-} \\left| e_{n,t}^{\\mathrm{bid}} \\right|}{\\sum_{n \\in \\mathcal{PA}^+} e_{n,t}^{\\mathrm{bid}}}, \\qquad \\mathcal{PA}^- = \\{\\, n \\mid e_{n,t}^{\\mathrm{bid}} \u003c 0,\\ n \\in \\mathcal{PA} \\,\\}, \\qquad \\mathcal{PA}^+ = \\{\\, n \\mid e_{n,t}^{\\mathrm{bid}} \\ge 0,\\ n \\in \\mathcal{PA} \\,\\}","formalization_origin":"source","template_id":null,"members":["bidding.supply","bidding.demand","pricing.local"],"variable_refs":[],"parameter_refs":["theta-e-bid-SDR"],"evidence_ids":["v141-b-g07-ev-05"]},{"constraint_id":"v141-c-R008-C007","kind":"mathematical","role":"core","statement":"When the regional supply-and-demand ratio is between zero and one, the internal selling price equals the product of the export and retail prices divided by the quantity (retail price minus export price) times the supply-and-demand ratio plus the export price. Scope: SDR internal selling price within one energy sharing region at a given time step. Condition: 0 \u003c= SDR_t \u003c= 1.","expression":"p_t^{\\mathrm{sell}} = \\frac{r_t^{\\mathrm{export}} \\cdot r_t^{\\mathrm{retail}}}{\\left( r_t^{\\mathrm{retail}} - r_t^{\\mathrm{export}} \\right) \\cdot SDR_t + r_t^{\\mathrm{export}}}, \\quad 0 \\le SDR_t \\le 1","formalization_origin":"source","template_id":null,"members":["bidding.supply","bidding.demand","pricing.local"],"variable_refs":[],"parameter_refs":["theta-r-export","theta-r-retail"],"evidence_ids":["v141-b-g07-ev-05"]},{"constraint_id":"v141-c-R008-C008","kind":"mathematical","role":"core","statement":"When the regional supply-and-demand ratio is between zero and one, the internal buying price equals the internal selling price times the supply-and-demand ratio plus the retail price times one minus the supply-and-demand ratio. Scope: SDR internal buying price within one energy sharing region at a given time step. Condition: 0 \u003c= SDR_t \u003c= 1.","expression":"p_t^{\\mathrm{buy}} = p_t^{\\mathrm{sell}} \\cdot SDR_t + r_t^{\\mathrm{retail}} \\left( 1 - SDR_t \\right), \\quad 0 \\le SDR_t \\le 1","formalization_origin":"source","template_id":null,"members":["bidding.supply","bidding.demand","pricing.local"],"variable_refs":[],"parameter_refs":["theta-r-export","theta-r-retail"],"evidence_ids":["v141-b-g07-ev-05"]}],"pi":[{"evidence_id":"v141-b-g02-e11","location":{"location_id":"src-d485825b0d-p06-c1r4__v141-a-M01-pricing","page":6,"printed_page":null,"section":"3.2.3","anchor_text":"Nagent trades with the retailer, including the prices at which the co- asordinator buys and sells th","equation_id":"6","figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"Taking the information in the environment as input, the coordinator agent runs the pricing model to generate the internal trading price to be issued to the prosumer agents. The pricing model is described as:\np^{\\mathrm{internal}} = Pricing (p^{\\mathrm{external}} ,e^{\\mathrm{bid}} ,p^{\\mathrm{bid}} )\n            T                                                       (6)\nwhere Pricing is the abstract function for generating the internal price."},{"evidence_id":"v141-b-g02-e16","location":{"location_id":"src-d485825b0d-p07-c1r2__v141-a-M04-participation","page":7,"printed_page":null,"section":"3.3","anchor_text":"p y/ y gy balance within the energy sharing region. P2P energy sharing in grid- m connected microgri","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-07.png","occurrence_role":"condition"},"source_text":"it is assumed that the retailer passively oﬀers/purchases unlimited power at pre-announced retail/export prices, and the export prices are assumed lower than retail prices, as all the known P2P energy sharing studies did [14–17]. Given this assumption, the scenarios where the prosumers directly negotiate with the retailer are equivalent with the paradigm shown in Fig. 2. This is because with this assumption, the internal prices have to be bounded between the retail and export prices (as shown in all the known P2P energy sharing mechanisms) and thus all the prosumers will ﬁrst consider to trade with other prosumers and last choose to go to the retailer (only when the energy is not balanced) [14–17]."},{"evidence_id":"v141-b-g07-ev-05","location":{"location_id":"src-d485825b0d-p26-c2r3__v141-a-M01-pricing","page":26,"printed_page":"1018","section":"A.2.1","anchor_text":"(A22) (A23) il price between the coordinator and the retailer as illustrated in Fig. 2; SDR haring r","equation_id":"A19-A23","figure_id":null,"table_id":null,"image_ref":"pages/page-26.png","occurrence_role":"formula"},"source_text":"With the energy bids from all the prosumers, the coordinator calculates the internal selling price by\n\np_t^{sell} = \\begin{cases} \\frac{r_t^{export} \\cdot r_t^{retail}}{(r_t^{retail} - r_t^{export}) \\cdot SDR_t + r_t^{export}}, & 0 \\le SDR_t \\le 1 \\\\ r_t^{export}, & SDR_t > 1 \\end{cases}  (A19)\n\nand the internal buying price by\n\np_t^{buy} = \\begin{cases} p_t^{sell} \\cdot SDR_t + r_t^{retail}(1 - SDR_t), & 0 \\le SDR_t \\le 1 \\\\ r_t^{export}, & SDR_t > 1 \\end{cases}  (A20)\n\nin which\n\nSDR_t = \\frac{\\sum_{n \\in \\mathcal{P}\\mathcal{A}^-} |e_{n,t}^{bid}|}{\\sum_{n \\in \\mathcal{P}\\mathcal{A}^+} e_{n,t}^{bid}}  (A21)\n\nwhere\n\n\\mathcal{P}\\mathcal{A}^- = \\{ n \\mid e_{n,t}^{bid} \u003c 0, n \\in \\mathcal{P}\\mathcal{A} \\}  (A22)\n\nand\n\n\\mathcal{P}\\mathcal{A}^+ = \\{ n \\mid e_{n,t}^{bid} \\ge 0, n \\in \\mathcal{P}\\mathcal{A} \\}.  (A23)\n\nIn Formulas (A19)-(A23), r_t^{export} and r_t^{retail} are the export and retail price between the coordinator and the retailer as illustrated in Fig. 2; SDR represents the supply and demand ratio of the whole P2P energy sharing region. Formulas (A19)-(A23) establish the pricing model in the coordinator agent under the SDR mechanism."},{"evidence_id":"v141-b-g02-e09","location":{"location_id":"src-d485825b0d-p06-c1r2__v141-a-M01-bidding","page":6,"printed_page":null,"section":"3.2.2","anchor_text":"Fig. 3. Abstract architecture of a prosumer agent. M th submitted to the coordinator agent. Therefor","equation_id":"4","figure_id":"Fig. 3","table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"Therefore, the set of actions of the prosumer agent is denoted as\n   \\mathcal{A}_{PA} = \\{x ,e^{\\mathrm{bid}},[p^{\\mathrm{bid}} ]\\}                                                (4)\nwhere e^{\\mathrm{bid}} and p^{\\mathrm{bid}} represent the energy bid and price bid, respectively. Note that in some mechanisms only energy bid is needed [16,17], so the p^{\\mathrm{bid}} is put into a bracket to show it is optional."},{"evidence_id":"v141-b-g02-e10","location":{"location_id":"src-d485825b0d-p06-c1r3__v141-a-M01-coordination","page":6,"printed_page":null,"section":"3.2.3","anchor_text":"p s put to a ac et to s o t s opt o a . To summarize, the abstract architecture of a prosumer agent ","equation_id":"5","figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"Therefore, the environment of the coordinator agent is denoted as\n CA = \\{p^{\\mathrm{external}} ,e^{\\mathrm{bid}} ,p^{\\mathrm{bid}} \\}                                              (5)\nwhere p^{\\mathrm{external}} represents the electricity price at which the coordinator agent trades with the retailer, including the prices at which the coordinator buys and sells the electricity from and to the retailer (termed as “retail price” and “export price” respectively in this paper). Note that in this paper the retail and export prices are considered as non-dynamic ones, i.e. the prices are known exactly by the coordinator beforehand and will not change with the amount of power and energy exchanged in real time."},{"evidence_id":"v141-b-g07-ev-04","location":{"location_id":"src-d485825b0d-p26-c2r2__v141-a-M01-bidding","page":26,"printed_page":"1018","section":"A.2.1","anchor_text":"p g y ⎫ ∈ T ⎬⎭ (A18) he decision-making model consisting of Formulas (A1)–(A17). With the energy ell","equation_id":"A18","figure_id":null,"table_id":null,"image_ref":"pages/page-26.png","occurrence_role":"formula"},"source_text":"In the SDR mechanism, prosumers are required to provide energy bids for the coordinator at every iteration. Specifically, based on the results of the decision-making model presented in Section A.1, the energy bid of a prosumer is given by\n\ne^{bid} = \\left\\{ e_t^{bid} \\mid e_t^{bid} = \\left( \\sum_{\\delta \\in \\mathcal{A}_f} x_{\\delta,t}^* \\right) + \\left( \\frac{x_t^{ch*}}{\\eta^{ch}} + x_t^{dis*} \\eta^{dis} \\right) + P_t^{must-run} - P_{PV,t}, t \\in T \\right\\}  (A18)\n\nin which x^* = \\{x_{\\delta,t}^*, x_t^{ch*}, x_t^{dis*}\\}, \\delta \\in \\mathcal{A}_f, t \\in T are the optimal solution of the decision-making model consisting of Formulas (A1)-(A17)."}],"field_notes":{"empty_E_reason":null,"empty_x_reason":"No design-selection or operational decision variable exists within this rule's scope. Under the SDR realization the coordinator applies a fixed closed-form pricing model: SDR_t, p_t^sell, p_t^buy and p^internal are defined quantities computed from already-submitted bids e_{n,t}^bid and the pre-announced external prices r_t^retail, r_t^export (the source states these prices are non-dynamic and known to the coordinator beforehand), and the source gives no optimisation or choice problem at the pricing stage. The genuine decision variables of the surrounding mechanism (device operating schedules x and the resulting bid quantities, source Formula (3)/(A1)-(A17), Formula (A18)) belong to the prosumer agents' decision-making model and the bidding rules, not to this pricing rule.","empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-participation","v141-a-M01-pricing","v141-a-M04-participation"],"extras":{"decision_anchor":"pricing.local","graph_fact_supports":[[{"evidence_id":"v141-b-g07-ev-05","quote":"With the energy bids from all the prosumers, the coordinator calculates the internal selling price by"},{"evidence_id":"v141-b-g07-ev-05","quote":"\\mathcal{P}\\mathcal{A}^- = \\{ n \\mid e_{n,t}^{bid} \u003c 0, n \\in \\mathcal{P}\\mathcal{A} \\}"},{"evidence_id":"v141-b-g07-ev-05","quote":"SDR represents the supply and demand ratio of the whole P2P energy sharing region."}],[{"evidence_id":"v141-b-g07-ev-05","quote":"With the energy bids from all the prosumers, the coordinator calculates the internal selling price by"},{"evidence_id":"v141-b-g07-ev-05","quote":"\\mathcal{P}\\mathcal{A}^+ = \\{ n \\mid e_{n,t}^{bid} \\ge 0, n \\in \\mathcal{P}\\mathcal{A} \\}."},{"evidence_id":"v141-b-g07-ev-05","quote":"SDR represents the supply and demand ratio of the whole P2P energy sharing region."}],[{"evidence_id":"v141-b-g02-e11","quote":"Taking the information in the environment as input, the coordinator agent runs the pricing model to generate the internal trading price to be issued to the prosumer agents."},{"evidence_id":"v141-b-g07-ev-05","quote":"Formulas (A19)-(A23) establish the pricing model in the coordinator agent under the SDR mechanism."}],[{"evidence_id":"v141-b-g02-e16","quote":"it is assumed that the retailer passively oﬀers/purchases unlimited power at pre-announced retail/export prices, and the export prices are assumed lower than retail prices"},{"evidence_id":"v141-b-g02-e16","quote":"the internal prices have to be bounded between the retail and export prices"}],[{"evidence_id":"v141-b-g07-ev-05","quote":"p_t^{sell} = \\begin{cases} \\frac{r_t^{export} \\cdot r_t^{retail}}{(r_t^{retail} - r_t^{export}) \\cdot SDR_t + r_t^{export}}, & 0 \\le SDR_t \\le 1 \\\\ r_t^{export}, & SDR_t > 1 \\end{cases}  (A19)"},{"evidence_id":"v141-b-g07-ev-05","quote":"p_t^{buy} = \\begin{cases} p_t^{sell} \\cdot SDR_t + r_t^{retail}(1 - SDR_t), & 0 \\le SDR_t \\le 1 \\\\ r_t^{export}, & SDR_t > 1 \\end{cases}  (A20)"}]],"C2_formalization":{"graph_sha256":"fde3eb20bee1c2bde5335c1c57989368c34a308a746b4e47946c3aff8a832d37","applicability":"formalized","reason":"This rule is a deterministic pricing rule (pricing.local) in the SDR realization of mechanism v141-a-M01. The source gives it in closed form: submitted signed net-energy bids e_{n,t}^{bid} form the regional supply-and-demand ratio SDR_t (Formulas (A21)-(A23), with supply bidders PA^- = {n | e_{n,t}^{bid} \u003c 0} and demand bidders PA^+ = {n | e_{n,t}^{bid} >= 0}), which in turn drives the coordinator's internal selling price p_t^{sell} (A19) and internal buying price p_t^{buy} (A20); the abstract coordinator-side relation is Formula (6) of the framework. All five existing phi entries are returned unchanged in constraint_id, statement, role, members and original evidence_ids, and were given expressions only where the verified source supplies them (C001: SDR supply term; C002: SDR demand term; C003: Formula (6); C004: the stated bound of internal prices between the export and retail prices under the export\u003cretail condition; C005: the SDR_t>1 branch of (A19)/(A20)). Three further source-supported constraints were added for the parts of the pricing model no existing constraint covers: the SDR_t ratio definition with (A22)-(A23), and the 0 \u003c= SDR_t \u003c= 1 branches of (A19) and (A20). No design-selection or operational decision variable is declared: within this rule the coordinator applies a fixed formula, and the priced outputs (SDR_t, p_t^{sell}, p_t^{buy}, p^{internal}) are defined quantities rather than decisions; the fixed inputs (non-dynamic external retail/export prices and the received bids) are recorded as parameters. The frozen graph is sufficient to represent every transcribed expression (pricing.local, with E001/E002 carrying demand/supply bids in and E003 carrying the coordinator's pricing role), so no C.1 revision is requested. Uncertainty: all B evidence cited here is UNREVIEWED under this experiment's policy (no B source audit, no independent C.2 review, no Agent E); this output makes no claim that B transcription or downstream science has passed source review, and Eq. (6)'s printed placement of T (subscript on Pricing versus a separate horizon symbol) is left as an unresolved typographic detail that does not change the constraint's meaning.","bindings":[{"object_id":"theta-r-export","node_ids":["coordination.local_operator","pricing.local"],"edge_ids":["v141-c-R008-E003"],"rationale":"The export price is the price at which the coordinator settles energy with the retailer and is an input of the local pricing formula; it therefore belongs to the coordinator node (which trades with the retailer on behalf of the region) and to the pricing node. E003 is the frozen edge linking the coordinator's pricing role to pricing.local, so the parameter is anchored there."},{"object_id":"theta-r-retail","node_ids":["coordination.local_operator","pricing.local"],"edge_ids":["v141-c-R008-E003"],"rationale":"Same anchoring as the export price: the retail price at which the coordinator buys from the retailer is part of the coordinator's pricing environment and enters the local pricing formulas, represented by the frozen coordinator-to-pricing edge E003."},{"object_id":"theta-e-bid-SDR","node_ids":["bidding.supply","bidding.demand","pricing.local"],"edge_ids":["v141-c-R008-E001","v141-c-R008-E002"],"rationale":"Submitted signed net-energy bids are exactly the quantities carried from the bidding nodes into local pricing: negative bids are supply (edge E002 from bidding.supply) and nonnegative bids are demand (edge E001 from bidding.demand)."},{"object_id":"theta-p-external","node_ids":["coordination.local_operator","pricing.local"],"edge_ids":["v141-c-R008-E003"],"rationale":"p^external is part of the coordinator agent's environment (source Eq. (5)) and is consumed by the coordinator's pricing model, i.e. it sits on the coordinator-to-pricing relation represented by the frozen edge E003."},{"object_id":"theta-e-bid","node_ids":["bidding.supply","bidding.demand","pricing.local"],"edge_ids":["v141-c-R008-E001","v141-c-R008-E002"],"rationale":"The framework-level energy bids are the submitted quantities flowing from the bidding nodes into the coordinator's pricing model; the frozen edges E001/E002 are the graph's representation of submitted bids reaching pricing.local."},{"object_id":"theta-p-bid","node_ids":["bidding.supply","bidding.demand"],"edge_ids":["v141-c-R008-E001","v141-c-R008-E002"],"rationale":"The price bid is a (optional) bid submitted by prosumer agents alongside the energy bid, so it is represented by the two submitted-bid nodes; the frozen graph has no dedicated price-bid node, and the edges E001/E002 are the closest representation of prosumer submissions reaching the coordinator's pricing model."},{"object_id":"v141-c-R008-C001","node_ids":["bidding.supply","pricing.local"],"edge_ids":["v141-c-R008-E002"],"rationale":"The supply-side term of the supply-and-demand ratio (absolute total of negative net-energy bids over PA^-) is the quantity that the frozen edge E002 carries from bidding.supply into pricing.local."},{"object_id":"v141-c-R008-C002","node_ids":["bidding.demand","pricing.local"],"edge_ids":["v141-c-R008-E001"],"rationale":"The demand-side term of the supply-and-demand ratio (total of nonnegative net-energy bids over PA^+) is the quantity that the frozen edge E001 carries from bidding.demand into pricing.local."},{"object_id":"v141-c-R008-C003","node_ids":["coordination.local_operator","pricing.local"],"edge_ids":["v141-c-R008-E003"],"rationale":"The constraint identifies the coordinator as the agent running the pricing model; the frozen edge E003 already attaches this constraint to the coordinator-to-pricing relation. Formalization detail: the source prints T beneath/after the function name Pricing, so the subscript on Pricing in the expression is a rendering of that printed T (horizon/typographic placement ambiguous) and does not alter the relation."},{"object_id":"v141-c-R008-C004","node_ids":["pricing.local"],"edge_ids":[],"rationale":"The bound is a property of the internal prices produced at pricing.local; the frozen graph contains no node for the retailer's external prices (they are modelled here as parameters), so no edge is attached."},{"object_id":"v141-c-R008-C005","node_ids":["pricing.local"],"edge_ids":[],"rationale":"The SDR_t > 1 branch sets the two internal prices produced at pricing.local; it involves no relationship between distinct frozen nodes, hence no edge."},{"object_id":"v141-c-R008-C006","node_ids":["bidding.supply","bidding.demand","pricing.local"],"edge_ids":["v141-c-R008-E001","v141-c-R008-E002"],"rationale":"The ratio is formed from both bid streams at the pricing node: numerator from supply bids (E002), denominator from demand bids (E001)."},{"object_id":"v141-c-R008-C007","node_ids":["bidding.supply","bidding.demand","pricing.local"],"edge_ids":["v141-c-R008-E001","v141-c-R008-E002"],"rationale":"The selling price is computed at pricing.local as a function of SDR_t, which is itself formed from the supply and demand bid streams entering along E002 and E001; the external retail/export prices are parameter inputs."},{"object_id":"v141-c-R008-C008","node_ids":["bidding.supply","bidding.demand","pricing.local"],"edge_ids":["v141-c-R008-E001","v141-c-R008-E002"],"rationale":"The buying price is computed at pricing.local from the selling price and SDR_t, i.e. from the same bid streams entering along E001/E002, with the retail price as a parameter input."}],"revision_requests":[]},"C2_delivery":{"raw_sha256":"7d26d8e94aa0fac49560fda7f5babef9c0b72c3f3caeac545e257ed52964ec54","delivery_payload_sha256":"9a815b663f7718e40748e71ff35520d21ccd48a71f2baa15470d58a44e2724de","changes":[{"path":"theta.0.value.kind","before":"symbolic","after":"unspecified","reason":"Variant tag follows supplied value fields; no value, symbol or scientific statement is added, removed or rewritten."},{"path":"theta.1.value.kind","before":"symbolic","after":"unspecified","reason":"Variant tag follows supplied value fields; no value, symbol or scientific statement is added, removed or rewritten."},{"path":"theta.2.value.kind","before":"symbolic","after":"unspecified","reason":"Variant tag follows supplied value fields; no value, symbol or scientific statement is added, removed or rewritten."},{"path":"theta.3.value.kind","before":"symbolic","after":"unspecified","reason":"Variant tag follows supplied value fields; no value, symbol or scientific statement is added, removed or rewritten."},{"path":"theta.4.value.kind","before":"symbolic","after":"unspecified","reason":"Variant tag follows supplied value fields; no value, symbol or scientific statement is added, removed or rewritten."},{"path":"theta.5.value.kind","before":"symbolic","after":"unspecified","reason":"Variant tag follows supplied value fields; no value, symbol or scientific statement is added, removed or rewritten."}],"scientific_fields_unchanged":true,"request_graph_sha256":"fde3eb20bee1c2bde5335c1c57989368c34a308a746b4e47946c3aff8a832d37","scientific_correctness_verified":false}},"quarantined_references":[]}});
